pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // restrict to admissible amounts: at least 1 wei, capped to avoid overflow in test helper
        amount = bound(amount, 1, 1e36);
        // unlockTime can be anything, but we need block.timestamp later; set it up
        vm.warp(100000);
        unlockTime = bound(unlockTime, 0, 200000);

        // deploy the adversarial re-entrant attacker
        ReEntrantAttacker attacker = new ReEntrantAttacker(c, unlockTime);
        vm.deal(address(attacker), amount);

        // the attacker calls Put with the fuzzed amount and unlockTime
        attacker.attack{value: amount}();

        // After the attack sequence completes, the invariant:
        // sum of all on-chain Acc balances must equal the contract's actual Ether balance.
        // The reference satisfies this for all inputs; the buggy version breaks it because
        // the re-entrant call corrupts the balance update.
        assertTrue(c.Acc(address(attacker)).balance == address(c).balance);
    }
}

contract ReEntrantAttacker {
    C public target;
    uint256 public unlockTime;
    bool private attacking;

    constructor(C _target, uint256 _unlockTime) {
        target = _target;
        unlockTime = _unlockTime;
        attacking = false;
    }

    function attack() external payable {
        require(!attacking, "already attacking");
        attacking = true;
        target.Put{value: msg.value}(unlockTime);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // re-enter Put with zero value to exploit the missing reentrancy guard
            target.Put{value: 0}(unlockTime);
        }
    }
}

