pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime) public {
        vm.assume(value > 0 && value < 1000 ether);
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), value);
        attacker.attack{value: value}(unlockTime);
        uint256 sum;
        for (uint256 i = 0; i < attacker.knownParticipantsLength(); i++) {
            address participant = attacker.knownParticipants(i);
            (, uint256 bal) = c.Acc(participant);
            sum += bal;
        }
        assertTrue(sum == address(c).balance);
