pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Restrict amounts to admissible range (prevent overflow in deposit, keep wide)
        amount = bound(amount, 1, type(uint128).max);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint64).max);

        // Deploy adversarial re-entrant attacker that calls Put again during Collect
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), 10 ether);

        // Record initial balance of contract C
        uint256 balBefore = address(c).balance;

        // Attacker deposits via Put, triggering reentrancy during its own Collect
        vm.prank(address(attacker));
        attacker.attack{value: amount}(unlockTime);

        uint256 balAfter = address(c).balance;

        // Property: C's balance must be >= initial balance + amount deposited exactly once.
        // In correct version, reentrancy guard blocks the reentered Put, so only one deposit occurs.
        // In buggy version, guard unlocks before body, allowing reentered Put, causing double deposit.
        assertTrue(balAfter == balBefore + amount);
    }
}

contract Attacker {
    C public target;
    uint256 private reentered;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 unlockTime) external payable {
        reentered = 0;
        target.Put{value: msg.value}(unlockTime);
    }

    receive() external payable {
        if (reentered < 1) {
            reentered++;
            // Re-enter target's Put while Collect is still executing (transfer to this contract)
            target.Put{value: 0}(0);
        }
    }
}

