pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        vm.assume(unlockTime <= type(uint256).max);

        address caller = address(0x123);
        vm.deal(caller, amount);
        vm.prank(caller);

        try c.Put{value: amount}(unlockTime) returns () {
            // After a successful Put, the reentrancy guard should be locked.
            // The buggy version sets locked_ to false during the modifier, then sets it to true after the function body,
            // leaving the guard permanently unlocked. We can detect this by checking if a subsequent re-entrant call
            // is allowed. We simulate a re-entrant call by making a low-level call that attempts to re-enter in the same transaction.
            // However, since we cannot re-enter in the same call with vm.prank, we use a re-entrant attacker helper.
            // But for the fuzz test we simply check that after the call, the guard remains locked. Since locked_ is internal,
            // we exploit the fact that if locked_ is false, a same-block re-entrant call would succeed, but we need an adversarial caller.
            // Wait, locked_ is internal and has no getter, so we cannot read it directly. The property must be observed through
            // the public/external surface. 
            // The invariant: after any successful call to Put, the reentrancy guard remains locked, so a subsequent call in the same
            // transaction (re-entrancy) would fail. Since we are not in a re-entrant scenario, we can check that a subsequent call
            // from an EOA succeeds, but that doesn't distinguish. The difference is about re-entrancy safety.
            // 
            // ALTERNATIVE: The bug leaves locked_ = true after the call instead of false. In the original, locked_ is restored to false.
            // In the buggy, locked_ ends up true. This means the original allows re-entry later (different transactions), but the buggy
            // permanently locks the contract (no further nonReentrant_ calls possible). However, this is the opposite of the typical
            // reentrancy bug. Let's re-read the mutant: 
            // Original: locked_ = true; _; locked_ = false;
            // Mutant: locked_ = false; _; locked_ = true;
            // So: original starts false, sets to true, runs body, sets to false -> final false.
            // Mutant: starts false, sets to false (no change), runs body, sets to true -> final true.
            // After a call, the original leaves locked_ = false, allowing future calls; the mutant leaves locked_ = true, 
            // blocking all future calls. That's the invariant: The original allows repeated Put calls (non-reentrant guard resets),
            // while the buggy one blocks them after the first call.
            // We can test this by doing a second Put call and seeing if it reverts.
            vm.prank(caller);
            try c.Put{value: amount}(unlockTime) returns () {
                // If second call succeeds, locked_ was false, so it's the original behavior.
                // If it reverts, locked_ was true, so buggy.
                assertTrue(true); // passes for original
            } catch {
                assertTrue(false); // fails for original
            }
        } catch {
            // First call failed, we can't test property, but we assume inputs are valid enough to succeed.
            // We could skip, but the fuzzer will find valid inputs.
        }
    }
}

