pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt, uint256 warpTime) public {
        // Bound values to avoid overflow and keep within practical limits
        deposit1 = bound(deposit1, 0, 1 ether);
        deposit2 = bound(deposit2, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        warpTime = bound(warpTime, 1, 1 days);

        address user = address(0x1234);
        vm.deal(user, deposit1 + deposit2);

        // First deposit
        vm.prank(user);
        c.Put{value: deposit1}(0);

        // Warp to ensure unlock time passed for collection
        uint256 unlockTime = c.Acc(user).unlockTime;
        vm.warp(unlockTime + warpTime);

        // Second deposit (to accumulate balance)
        vm.prank(user);
        c.Put{value: deposit2}(0);

        // Track total deposited for user
        uint256 totalDeposited = deposit1 + deposit2;

        // Attempt to collect some amount, ensuring it's <= balance and >= MinSum, and time > unlockTime
        uint256 userBalance = c.Acc(user).balance;
        uint256 minSum = c.MinSum();
        vm.assume(userBalance >= collectAmt && userBalance >= minSum && c.Acc(user).unlockTime < block.timestamp);

        vm.prank(user);
        c.Collect(collectAmt);

        // After collection, balance should be totalDeposited minus collected amount (if collect succeeded)
        uint256 finalBalance = c.Acc(user).balance;

        // Since depositing doesn't revert, we compute expected: total deposited minus successfully collected
        // But collection might fail if conditions not met; our assume ensures it succeeds.
        // For the mutant, balance will be totalDeposited + 2 (one extra per Put) minus collectAmt.
        // The invariant: balance + collectAmt == totalDeposited (no extra wei).
        assertTrue(finalBalance + collectAmt == totalDeposited);
    }
}

