pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint128 depositAmount, uint128 collectAmount) public {
        // 1. Admissible domain: realistic widths, avoid overflow and zero-value waste
        vm.assume(actor != address(0));
        depositAmount = uint128(bound(depositAmount, 1, type(uint64).max));
        collectAmount = uint128(bound(collectAmount, 1, type(uint64).max));

        // 2. Fund actor and make two deposits via Put to trigger the mutant's +1 per call
        vm.deal(actor, uint256(depositAmount) * 2);
        vm.startPrank(actor);
        // First deposit
        c.Put{value: depositAmount}(uint256(0));
        // Second deposit, using a far-future unlock time so Collect is not blocked by timestamp
        c.Put{value: depositAmount}(type(uint256).max);
        vm.stopPrank();

        // Warp past unlock time to allow Collect
        vm.warp(type(uint256).max);

        // Read pre-collect balance
        uint256 preBalance = c.Acc(actor).balance;

        // 3. Attempt Collect with a valid amount ≤ deposited total
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        // If collect succeeded, the balance reduction must exactly equal the collected amount.
        // The mutant adds +1 per Put, so for two Puts the balance is inflated by 2 wei,
        // violating the equality.
        if (ok) {
            uint256 postBalance = c.Acc(actor).balance;
            assertTrue(postBalance == preBalance - collectAmount);
        }
    }
}

