pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount1, uint256 putAmount2, uint256 collectAmount) public {
        // Keep amounts within reasonable bounds to avoid overflow in tracking and to allow meaningful Collect attempts.
        putAmount1 = bound(putAmount1, 1, 1e30);
        putAmount2 = bound(putAmount2, 1, 1e30);
        collectAmount = bound(collectAmount, 1, 1e30);

        // Use a fresh account that has never interacted with the contract.
        address actor = address(0xbeef);
        vm.assume(actor != address(this));

        // Track the total wei that flows into Put (including fallback-received wei, but the fallback calls Put(0) with its value).
        uint256 expectedBalance = 0;

        // First deposit via Put
        vm.deal(actor, putAmount1);
        vm.prank(actor);
        c.Put{value: putAmount1}(0);
        expectedBalance += putAmount1;

        // Second deposit via fallback (which internally calls Put(0) with the same value)
        vm.deal(actor, putAmount2);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: putAmount2}("");
        require(success, "fallback call failed");
        expectedBalance += putAmount2;

        // Advance time past any unlockTime (default 0) to allow Collect
        vm.warp(block.timestamp + 1);

        // Attempt a Collect. It may partially or fully succeed depending on amount.
        uint256 preBalance = c.Acc(actor).balance;
        uint256 collectable = collectAmount > preBalance ? preBalance : collectAmount;
        if (collectable > 0) {
            vm.prank(actor);
            c.Collect(collectAmount);
            // Only subtract if the collect actually transferred the amount (it always does if unlockTime passed and balance >= MinSum).
            // Because MinSum is 1 ether, but our high bounds guarantee balance >= MinSum after deposits.
            expectedBalance -= collectable;
        }

        // The invariant: stored balance == net Ether deposited via Put/fallback minus collected.
        // The mutant adds +1 wei on every direct Put call (but not on the fallback→Put path because the fallback sends
        // the whole msg.value to Put, which then adds +1, so both paths add +1). Actually the fallback calls Put(0)
        // which executes the same mutated line, so both paths are affected. Thus the stored balance will be
        // expected + number_of_Put_calls (which is 2 in this test). The test fails for the mutant because the
        // stored balance equals expectedBalance + 2 while the invariant requires strict equality.
        assertTrue(c.Acc(actor).balance == expectedBalance);
    }
}

