import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint128 depositAmt, uint8 collectAmt8, uint48 warpDelta) public {
        // Restrict to reasonable values and ensure _unlockTime is far enough in the future
        uint256 collectAmt = uint256(collectAmt8);
        depositAmt = uint128(bound(depositAmt, 1 ether, 1000 ether));
        vm.assume(_unlockTime > block.timestamp);
        vm.assume(collectAmt <= depositAmt);
        // warpDelta is a small positive offset, ensuring we are strictly before the intended unlock time
        vm.assume(warpDelta > 0);
        uint256 futureUnlock = _unlockTime;
        vm.assume(futureUnlock - block.timestamp > warpDelta);

        address alice = address(0x1000);
        vm.deal(alice, depositAmt);

        // Alice deposits with a future unlock time
        vm.prank(alice);
        c.Put{value: depositAmt}(futureUnlock);

        // Warp to a timestamp that is still before the intended unlock time, but after the time the bug records
        uint256 targetTime = block.timestamp + warpDelta;
        vm.assume(targetTime < futureUnlock);
        vm.warp(targetTime);

        // Alice tries to collect some amount; this should revert because we are before the requested unlock time
        vm.prank(alice);
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
