        // Actually, the buggy version does acc.balance = add_uint256(acc.balance, _am), which could overflow if too large, but we bounded putAmt.
        // The property: balAfter must not be greater than balBefore (since collection should never increase balance).
        // This captures the bug: bug makes it increase exactly by am, so balAfter > balBefore.
        assertTrue(balAfter <= balBefore);
    }
}

