contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 warpTime) public {
        // Keep amounts within reasonable ETH bounds to avoid overflow complications
        bound(putAmount, 1 ether, 1000 ether);
        bound(collectAmount, 1 ether, 1000 ether);
        // Ensure we are testing successful Collect conditions: balance >= MinSum (1 ether) and >= collectAmount
        vm.assume(putAmount >= 1 ether);
        vm.assume(putAmount >= collectAmount);
        // Ensure unlockTime is in the past for Collect to succeed
        vm.assume(warpTime > block.timestamp + 1);

        address actor = address(0x1234);
        vm.deal(actor, putAmount);

        // Put funds to establish balance and set unlockTime
        vm.prank(actor);
        c.Put{value: putAmount}(warpTime);

        // Warp to after unlockTime
        vm.warp(warpTime + 1);

        // Record contract ETH balance before Collect
        uint256 contractBalanceBefore = address(c).balance;

        // Perform Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        // Record contract ETH balance after Collect
        uint256 contractBalanceAfter = address(c).balance;

        // The reference contract decreases its ETH balance by collectAmount when Collect succeeds.
        // The buggy contract still sends ETH but records an internal balance increase, but the contract's
        // actual ETH balance still decreases by collectAmount because the low-level call transfers ETH out.
        // Wait, the bug is about internal balance increase, not ETH balance.
        // We need a rule that differentiates based on contract ETH balance.
        // After a successful Collect with a low-level call that doesn't revert, the contract's ETH balance
        // must have decreased by at least collectAmount (since some may be consumed by gas, but the transfer
        // is exactly collectAmount). The reference always decreases by collectAmount. The buggy version
        // still transfers collectAmount out, so contract ETH balance decreases by collectAmount too.
        // Thus ETH balance change is NOT the differentiator.
        // The difference is in the internal Acc balance mapping, which has a public getter.
        // We can assert on the internal balance after Collect.
        // But previous attempts were "caller's stored balance must decrease by collected amount" and
        // "caller's Acc balance must not exceed pre-Collect balance plus amount collected".
        // Let's try: after successful Collect, the caller's balance must equal the pre-Collect balance minus collectAmount.
        // That is exactly what the reference does, and the bug violates it.
        // We haven't tried asserting on the public getter Acc(actor).balance.
        // Since `Acc` mapping is public, we can call c.Acc(actor).balance.
        // The reference: c.Acc(actor).balance == putAmount - collectAmount.
        // The bug: c.Acc(actor).balance == putAmount + collectAmount.
        // So we can assert: assertEq(c.Acc(actor).balance, putAmount - collectAmount);
        // But that uses the exact amounts, which is a regression test, not a property.
        // We need a general property without referencing the exact input amounts.
        // Could we assert: c.Acc(actor).balance <= putAmount - collectAmount? No, because reference exactly equals.
        // Could we assert: c.Acc(actor).balance + collectAmount <= putAmount? That works for reference.
        // For reference: putAmount - collectAmount + collectAmount <= putAmount -> putAmount <= putAmount, true.
        // For bug: putAmount + collectAmount + collectAmount <= putAmount -> false for positive collectAmount.
        // So assertTrue(c.Acc(actor).balance + collectAmount <= putAmount) is a general rule that reference satisfies and bug breaks.
        // This doesn't rely on exact equality, just an inequality that holds for reference.
        uint256 balanceAfter = c.Acc(actor).balance;
        assertTrue(balanceAfter + collectAmount <= putAmount);
    }
}

